import 'package:flutter/material.dart';
import 'services/app_state.dart'; import 'models/models.dart'; import 'screens/login.dart'; import 'screens/student.dart'; import 'screens/teacher.dart'; import 'screens/profile.dart'; import 'widgets/ui.dart';
void main()=>runApp(const SkillForge());
class SkillForge extends StatefulWidget{const SkillForge({super.key});@override State<SkillForge> createState()=>_SkillForgeState();}
class _SkillForgeState extends State<SkillForge>{final state=AppState(); @override Widget build(BuildContext c)=>AnimatedBuilder(animation:state,builder:(_,__)=>MaterialApp(debugShowCheckedModeBanner:false,title:'SkillForge',theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,scaffoldBackgroundColor:bg,fontFamily:'Inter',colorScheme:ColorScheme.fromSeed(seedColor:accent,brightness:Brightness.dark)),initialRoute:'/login',routes:{'/login':(_)=>LoginScreen(state:state),'/home':(_)=>HomeShell(state:state)}));}
class HomeShell extends StatelessWidget{final AppState state;const HomeShell({super.key,required this.state});@override Widget build(BuildContext c){final teacher=state.role!=UserRole.student;final pages=teacher?[TeacherHome(state:state),ProfileScreen(state:state)]:[StudentHome(state:state),ProfileScreen(state:state)];return Scaffold(body:pages[state.currentIndex],bottomNavigationBar:NavigationBar(backgroundColor:panel,indicatorColor:accent.withOpacity(.15),selectedIndex:state.currentIndex,onDestinationSelected:state.setIndex,destinations:[NavigationDestination(icon:Icon(teacher?Icons.dashboard_outlined:Icons.home_outlined),selectedIcon:Icon(teacher?Icons.dashboard:Icons.home),label:teacher?'Dashboard':'Home'),const NavigationDestination(icon:Icon(Icons.insights_outlined),selectedIcon:Icon(Icons.insights),label:'Profile')]));}}
